import { combineReducers } from 'redux';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import initialState from './initialState';
import { htmlEntities } from '../../../utils';
const positionToClassName = {
  before_fb: 'emthemesModezBannersBlockSidebar01',
  after_fb: 'emthemesModezBannersBlockSidebar02'
};
const positionToGroupName = {
  before_fb: 'above Facebook Like Box',
  after_fb: 'below Facebook Like Box'
};

const exportHTML = state => [...state.items.map(id => state.itemsById[id]).map(({
  id,
  link,
  img,
  alt,
  text,
  heading,
  btn,
  type,
  position
}) => (type === 'banner' ? [`<!-- Banner displays ${positionToGroupName[position]} -->`, `<div class="sidebarBlock sidebarBlock--banner ${positionToClassName[position]}">`, `  <div class="emthemesModez-bannersContainer">`, `    <div class="emthemesModez-banner">`, `      <div class="emthemesModez-banner-figure"><a href="${htmlEntities(link)}"><img class="emthemesModez-banner-image" src="${htmlEntities(img)}" alt="${htmlEntities(alt)}" title="${htmlEntities(alt)}" /></a></div>`, `    </div>`, `  </div>`, `</div>`] : type === 'text_block' ? [`<!-- Text Block displays ${positionToGroupName[position]} -->`, `<div class="sidebarBlock sidebarBlock--textBlock sidebarBlock--mobileCollapsible ${positionToClassName[position]}">`, `  <h5 class="sidebarBlock-heading is-open" data-collapsible="#sidebar-textBlock${id}" data-collapsible-disabled-breakpoint="medium">${heading}</h5>`, `  <div id="sidebar-textBlock${id}" class="sidebarBlock-content is-open">`, `    ${text}`, btn ? `    <p><a class="button" href="${htmlEntities(link)}">${btn}</a></p>` : '', `  </div>`, `</div>`] : [`<!-- Text displays ${positionToGroupName[position]} -->`, `<div class="sidebarBlock sidebarBlock--banner ${positionToClassName[position]}">${text}</div>`]).join('\n'))].join('\n\n');

const reducer = (state = {}, action) => {
  let {
    id,
    ...payload
  } = action.payload || {};

  switch (action.type) {
    case 'ADD_ITEM':
      id = state.itemNextId;
      return { ...state,
        items: [...state.items, id],
        itemsById: { ...state.itemsById,
          [id]: {
            id,
            ...payload
          }
        },
        itemNextId: id + 1
      };

    case 'UPDATE_ITEM':
      return { ...state,
        itemsById: { ...state.itemsById,
          [id]: { ...state.itemsById[id],
            ...payload
          }
        }
      };

    case 'DELETE_ITEM':
      const newItems = state.items.filter(_id => _id !== id);
      return { ...state,
        items: newItems,
        itemsById: newItems.reduce((newItemsById, id) => ({ ...newItemsById,
          [id]: state.itemsById[id]
        }), {}),
        itemNextId: Math.max(...newItems) + 1
      };

    case 'UPDATE_STATE':
      return { ...state,
        ...action.payload
      };

    case 'TOGGLE_COLLAPSE_GROUP':
      return { ...state,
        collapsedGroups: state.collapsedGroups.indexOf(action.payload.group) !== -1 ? state.collapsedGroups.filter(group => group !== action.payload.group) : [...state.collapsedGroups, action.payload.group]
      };

    case 'EXPORT_CODE':
      return { ...state,
        exportedHTML: exportHTML(state)
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const persistConfig = {
  key: 'SidebarBannerBuilderComponent',
  storage
};
export default combineReducers({
  SidebarBannerBuilderComponent: persistReducer(persistConfig, reducer)
});