import { combineReducers } from 'redux';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import initialState from './initialState';

const exportHTML = state => [`<div data-custom-tab>`, ...state.items.map(id => state.itemsById[id]).map(({
  title,
  content
}) => [`  <p data-custom-tab-title>${title}</p>`, `  <div>${content}</div>`].join('\n')), `</div>`].join('\n');

const reducer = (state = {}, action) => {
  let {
    id,
    ...payload
  } = action.payload || {};

  switch (action.type) {
    case 'ADD_ITEM':
      id = state.itemNextId;
      return { ...state,
        items: [...state.items, id],
        itemsById: { ...state.itemsById,
          [id]: {
            id,
            ...payload
          }
        },
        itemNextId: id + 1
      };

    case 'UPDATE_ITEM':
      return { ...state,
        itemsById: { ...state.itemsById,
          [id]: { ...state.itemsById[id],
            ...payload
          }
        }
      };

    case 'DELETE_ITEM':
      const newItems = state.items.filter(_id => _id !== id);
      return { ...state,
        items: newItems,
        itemsById: newItems.reduce((newItemsById, id) => ({ ...newItemsById,
          [id]: state.itemsById[id]
        }), {}),
        itemNextId: Math.max(...newItems) + 1
      };

    case 'UPDATE_STATE':
      return { ...state,
        ...action.payload
      };

    case 'EXPORT_CODE':
      return { ...state,
        exportedHTML: exportHTML(state)
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const persistConfig = {
  key: 'ProductCustomTabsBuilderComponent',
  storage
};
export default combineReducers({
  ProductCustomTabsBuilderComponent: persistReducer(persistConfig, reducer)
});