import { combineReducers } from 'redux';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import initialState from './initialState';

function exportHTML({
  content
}) {
  return `` + `<div id="emthemesModezBannersBlockAdvTopHeader" class="banners emthemesModezBannersBlockAdvTopHeader">\n` + `<div class="banner">${content}</div>\n` + `</div>`;
}

const reducer = (state = {}, action) => {
  switch (action.type) {
    case 'UPDATE_STATE':
      return { ...state,
        ...action.payload
      };

    case 'EXPORT_CODE':
      return { ...state,
        exportedHTML: exportHTML(state)
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const ormPersistConfig = {
  key: 'TopBannerBuilderComponent',
  storage
};
export default combineReducers({
  TopBannerBuilderComponent: persistReducer(ormPersistConfig, reducer)
});