import { Model, fk, attr } from 'redux-orm';
export class Banner extends Model {
  static reducer(action, Banner, session) {
    let banner;

    switch (action.type) {
      case 'CREATE_BANNER':
        Banner.create(action.payload);
        break;

      case 'UPDATE_BANNER':
        Banner.withId(action.payload.id).update(action.payload);
        break;

      case 'REMOVE_BANNER':
        Banner.withId(action.payload.id).delete();
        break;

      case 'ASSIGN_BANNER_GROUP':
        Banner.withId(action.payload.bannerId).bannerGroupId = action.payload.bannerGroupId;
        break;

      case 'TOGGLE_COLLAPSE_BANNER':
        banner = Banner.withId(action.payload.id);
        banner.update({
          collapsed: !banner.collapsed
        });
        break;

      default:
        break;
    }
  }

}
Banner.modelName = 'Banner';
Banner.fields = {
  id: attr(),
  img: attr(),
  alt: attr(),
  link: attr(),
  collapsed: attr(),
  bannerGroupId: fk('BannerGroup', 'banners')
};
export class BannerGroup extends Model {
  static reducer(action, BannerGroup, session) {
    let bannerGroup;

    switch (action.type) {
      case 'CREATE_BANNER_GROUP':
        BannerGroup.create(action.payload);
        break;

      case 'UPDATE_BANNER_GROUP':
        BannerGroup.withId(action.payload.id).update(action.payload);
        break;

      case 'REMOVE_BANNER_GROUP':
        bannerGroup = BannerGroup.withId(action.payload.id);
        bannerGroup.banners.delete();
        bannerGroup.delete();
        break;

      case 'TOGGLE_COLLAPSE_BANNER_GROUP':
        bannerGroup = BannerGroup.withId(action.payload.id);
        bannerGroup.update({
          collapsed: !bannerGroup.collapsed
        });
        break;

      default:
        break;
    }
  }

}
;
BannerGroup.modelName = 'BannerGroup';
BannerGroup.fields = {
  id: attr(),
  region: attr(),
  collapsed: attr(),
  menuId: fk('Menu', 'bannerGroups')
};
export class Menu extends Model {
  static reducer(action, Menu, session) {
    let menu;

    switch (action.type) {
      case 'CREATE_MENU':
        Menu.create(action.payload);
        break;

      case 'UPDATE_MENU':
        Menu.withId(action.payload.id).update(action.payload);
        break;

      case 'REMOVE_MENU':
        menu = Menu.withId(action.payload.id);
        menu.bannerGroups.toModelArray().map(bannerGroup => bannerGroup.banners.delete());
        menu.bannerGroups.delete();
        menu.delete();
        break;

      case 'TOGGLE_COLLAPSE_MENU':
        menu = Menu.withId(action.payload.id);

        if (action.payload.region) {
          if (menu.collapsedRegions.indexOf(action.payload.region) > -1) {
            menu.update({
              collapsedRegions: menu.collapsedRegions.filter(region => region !== action.payload.region)
            });
          } else {
            menu.update({
              collapsedRegions: [...menu.collapsedRegions, action.payload.region]
            });
          }
        } else {
          menu.update({
            collapsed: !menu.collapsed
          });
        }

        break;

      default:
        break;
    }
  }

}
Menu.modelName = 'Menu';
Menu.fields = {
  id: attr(),
  collapsed: attr(),
  collapsedRegions: attr({
    getDefault: () => []
  })
};