export const getState = store => store.ProductBannerBuilderComponent;

const getItemsState = store => getState(store) && getState(store).items ? getState(store).items : [];

const getItemById = (store, id) => getState(store) && getState(store).itemsById ? getState(store).itemsById[id] : null;

export const getItems = store => getItemsState(store).map(id => getItemById(store, id));