import { combineReducers } from 'redux';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import initialState from './initialState';
import { htmlEntities } from '../../../utils';

const exportHTML = state => [`<div id="emthemesModezBannersBlockAfterHeader" class="container emthemesModezBannersBlockAfterHeader">`, `<div class="emthemesModez-section emthemesModez-section--banners-one">`, `<div class="emthemesModez-section-inner">`, `<div class="emthemesModez-bannersContainer emthemesModez-bannersContainer--one">`, ...state.items.map(id => {
  const {
    link,
    img,
    alt,
    text,
    type
  } = state.itemsById[id];

  if (type === 'banner') {
    return [`<div class="emthemesModez-banner">`, `<div class="emthemesModez-banner-container"><a href="${htmlEntities(link)}"><img class="emthemesModez-banner-image" src="${htmlEntities(img)}" alt="${htmlEntities(alt)}" title="${htmlEntities(alt)}" /></a></div>`, `</div>`].join('\n');
  } else {
    return `<div class="emthemesModez-banner emthemesModez-banner--text">${text}</div>`;
  }
}), `</div>`, `</div>`, `</div>`, `</div>`].join('\n');

const reducer = (state = {}, action) => {
  let {
    id,
    ...payload
  } = action.payload || {};

  switch (action.type) {
    case 'ADD_ITEM':
      id = state.itemNextId;
      return { ...state,
        items: [...state.items, id],
        itemsById: { ...state.itemsById,
          [id]: {
            id,
            ...payload
          }
        },
        itemNextId: id + 1
      };

    case 'UPDATE_ITEM':
      return { ...state,
        itemsById: { ...state.itemsById,
          [id]: { ...state.itemsById[id],
            ...payload
          }
        }
      };

    case 'DELETE_ITEM':
      const newItems = state.items.filter(_id => _id !== id);
      return { ...state,
        items: newItems,
        itemsById: newItems.reduce((newItemsById, id) => ({ ...newItemsById,
          [id]: state.itemsById[id]
        }), {}),
        itemNextId: Math.max(...newItems) + 1
      };

    case 'UPDATE_STATE':
      return { ...state,
        ...action.payload
      };

    case 'EXPORT_CODE':
      return { ...state,
        exportedHTML: exportHTML(state)
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const persistConfig = {
  key: 'BannerBelowHeaderBuilderComponent',
  storage
};
export default combineReducers({
  BannerBelowHeaderBuilderComponent: persistReducer(persistConfig, reducer)
});