import { combineReducers } from 'redux';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import initialState from './initialState';
import { htmlEntities } from '../../../utils';

const exportHTML = state => [`<div id="emthemesModezBannersBlockAfterHeader" class="container emthemesModezBannersBlockAfterHeader supermarket-3promo" data-css="`, `  .supermarket-3promo .column { padding-top: .75rem; padding-bottom: .75rem }`, `  .supermarket-3promo .column + .column { border-top: 1px solid #ccc }`, `  .supermarket-3promo .column img { margin-right: .75rem }`, `  .papaSupermarket-pageType--default .supermarket-3promo ~ .body .page-content { margin-top: 0 }`, `  @media (min-width: 551px) {`, `    .supermarket-3promo { text-align: center }`, `    .supermarket-3promo .column + .column { border-top: 0; position: relative; }`, `    .supermarket-3promo .column + .column:before { content: ''; width: 0; height: calc(100% - 1.5rem); top: .75rem; left: 0; border-left: 1px solid #ccc; position: absolute; }`, `  }`, `">`, `  <div class="row">`, ...state.items.map(id => {
  const {
    link,
    img,
    alt,
    text,
    type
  } = state.itemsById[id];
  return [`    <div class="column medium-${Math.floor(12 / state.items.length)}">`, type === 'banner' ? `      <a href="${htmlEntities(link)}"><img src="${htmlEntities(img)}" alt="${htmlEntities(alt)}" title="${htmlEntities(alt)}" /></a>` : `      ${text}`, `    </div>`].join('\n');
}), `  </div>`, `  <script type="text/javascript">// <![CDATA[`, `  (function() {`, `    var style = document.createElement('style');`, `    style.innerHTML = document.querySelectorAll('.supermarket-3promo')[0].getAttribute('data-css');`, `    document.head.appendChild(style);`, `  })();`, `  // ]]></script>`, `</div>`].join('\n');

const reducer = (state = {}, action) => {
  let {
    id,
    ...payload
  } = action.payload || {};

  switch (action.type) {
    case 'ADD_ITEM':
      id = state.itemNextId;
      return { ...state,
        items: [...state.items, id],
        itemsById: { ...state.itemsById,
          [id]: {
            id,
            ...payload
          }
        },
        itemNextId: id + 1
      };

    case 'UPDATE_ITEM':
      return { ...state,
        itemsById: { ...state.itemsById,
          [id]: { ...state.itemsById[id],
            ...payload
          }
        }
      };

    case 'DELETE_ITEM':
      const newItems = state.items.filter(_id => _id !== id);
      return { ...state,
        items: newItems,
        itemsById: newItems.reduce((newItemsById, id) => ({ ...newItemsById,
          [id]: state.itemsById[id]
        }), {}),
        itemNextId: Math.max(...newItems) + 1
      };

    case 'UPDATE_STATE':
      return { ...state,
        ...action.payload
      };

    case 'EXPORT_CODE':
      return { ...state,
        exportedHTML: exportHTML(state)
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const persistConfig = {
  key: 'ThreeBannersBelowHeaderBuilderComponent',
  storage
};
export default combineReducers({
  ThreeBannersBelowHeaderBuilderComponent: persistReducer(persistConfig, reducer)
});