import { combineReducers } from 'redux';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import initialState from './initialState';

const exportHTML = state => [`<ul class="navUser-section emthemesModezBannersBlockTopHeaderBanner02">`, ...state.links.map(id => {
  const {
    link,
    title
  } = state.linksById[id];
  return `<li class="navUser-item"><a class="navUser-action" href="${link}">${title}</a></li>`;
}), `</ul>`].join('\n');

const reducer = (state = {}, action) => {
  let {
    id,
    ...payload
  } = action.payload || {};

  switch (action.type) {
    case 'ADD_LINK':
      id = state.linkNextId;
      return { ...state,
        links: [...state.links, id],
        linksById: { ...state.linksById,
          [id]: {
            id,
            ...payload
          }
        },
        linkNextId: id + 1
      };

    case 'UPDATE_LINK':
      return { ...state,
        linksById: { ...state.linksById,
          [id]: { ...state.linksById[id],
            ...payload
          }
        }
      };

    case 'DELETE_LINK':
      const newLinks = state.links.filter(_id => _id !== id);
      return { ...state,
        links: newLinks,
        linksById: newLinks.reduce((newLinksById, id) => ({ ...newLinksById,
          [id]: state.linksById[id]
        }), {}),
        linkNextId: Math.max(...newLinks) + 1
      };

    case 'UPDATE_STATE':
      return { ...state,
        ...action.payload
      };

    case 'EXPORT_CODE':
      return { ...state,
        exportedHTML: exportHTML(state)
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const persistConfig = {
  key: 'RightHeaderContentBuilderComponent',
  storage
};
export default combineReducers({
  RightHeaderContentBuilderComponent: persistReducer(persistConfig, reducer)
});