export const addItem = ({
  link = '',
  img = '',
  alt = '',
  text = '',
  collapsed = false,
  type = 'banner'
} = {}) => ({
  type: 'ADD_ITEM',
  payload: {
    link,
    img,
    alt,
    text,
    collapsed,
    type
  }
});
export const updateItem = banner => ({
  type: 'UPDATE_ITEM',
  payload: { ...banner
  }
});
export const deleteItem = id => ({
  type: 'DELETE_ITEM',
  payload: {
    id
  }
});
export const updateState = state => ({
  type: 'UPDATE_STATE',
  payload: { ...state
  }
});
export const exportCode = () => ({
  type: 'EXPORT_CODE',
  payload: {}
});
export const resetState = () => ({
  type: 'RESET_STATE',
  payload: {}
});