export const createBannerGroup = bannerGroup => ({
  type: 'CREATE_BANNER_GROUP',
  payload: { ...bannerGroup
  }
});
export const updateBannerGroup = bannerGroup => ({
  type: 'UPDATE_BANNER_GROUP',
  payload: { ...bannerGroup
  }
});
export const removeBannerGroup = id => ({
  type: 'REMOVE_BANNER_GROUP',
  payload: {
    id
  }
});
export const createBanner = banner => ({
  type: 'CREATE_BANNER',
  payload: { ...banner
  }
});
export const updateBanner = banner => ({
  type: 'UPDATE_BANNER',
  payload: { ...banner
  }
});
export const removeBanner = id => ({
  type: 'REMOVE_BANNER',
  payload: {
    id
  }
});
export const createMenu = menu => ({
  type: 'CREATE_MENU',
  payload: { ...menu
  }
});
export const updateMenu = menu => ({
  type: 'UPDATE_MENU',
  payload: { ...menu
  }
});
export const removeMenu = id => ({
  type: 'REMOVE_MENU',
  payload: {
    id
  }
});
export const exportJSON = () => ({
  type: 'EXPORT_JSON',
  payload: {
    force: true
  }
});
export const clearExportedJSON = () => ({
  type: 'EXPORT_JSON'
});
export const toggleCollapse = (entityClass, id = '', region = '') => {
  const typeMap = {
    Menu: 'TOGGLE_COLLAPSE_MENU',
    BannerGroup: 'TOGGLE_COLLAPSE_BANNER_GROUP',
    Banner: 'TOGGLE_COLLAPSE_BANNER'
  };
  return {
    type: typeMap[entityClass] || 'TOGGLE_COLLAPSE',
    payload: {
      id,
      region
    }
  };
};
export const resetState = () => ({
  type: 'RESET_STATE',
  payload: {}
});