import { combineReducers } from 'redux';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import initialState from './initialState';

const exportHTML = ({
  img,
  alt,
  heading,
  content
}) => [`<div id="emthemesModezBannersBlockNewsletterPopup" class="newsletterPopup">`, `  <div class="newsletterPopup-image"><img src="${img}" alt="${alt}" /></div>`, `  <div class="newsletterPopup-content">`, `    <h3 class="newsletterPopup-heading">${heading}</h3>`, `    <div class="newsletterPopup-description">${content}</div>`, `    <div id="newsletterPopup-form-placeholder" class="newsletterPopup-form"><span class="u-hiddenVisually" style="color: red;">FORM SHOWS HERE - DO NOT DELETE THIS RED LINE</span></div>`, `  </div>`, `</div>`].join('\n');

const reducer = (state = {}, action) => {
  switch (action.type) {
    case 'UPDATE_STATE':
      return { ...state,
        ...action.payload
      };

    case 'EXPORT_CODE':
      return { ...state,
        exportedHTML: exportHTML(state)
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const ormPersistConfig = {
  key: 'NewsletterPopupBuilderComponent',
  storage
};
export default combineReducers({
  NewsletterPopupBuilderComponent: persistReducer(ormPersistConfig, reducer)
});