import { combineReducers } from 'redux';
import reduceReducers from 'reduce-reducers';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import { createReducer } from 'redux-orm';
import orm from './orm';
import initialState from './initialState';

const reducer = (state = {
  exportedJSON: '',
  collapsed: false
}, action) => {
  const session = orm.session(state);

  const exportJSON = () => session.Menu.all().toModelArray().map(menu => {
    const {
      ref
    } = menu;

    const inRegion = (bannerGroups, region) => bannerGroups.filter({
      region
    }).toModelArray().map(bannerGroup => {
      const {
        refBannerGroup
      } = bannerGroup;
      return { ...refBannerGroup,
        banners: bannerGroup.banners.toRefArray()
      };
    });

    return { ...ref,
      rightRegion: {
        bannerGroups: inRegion(menu.bannerGroups, 'right')
      },
      bottomRegion: {
        bannerGroups: inRegion(menu.bannerGroups, 'bottom')
      }
    };
  });

  switch (action.type) {
    case 'TOGGLE_COLLAPSE':
      return { ...state,
        collapsed: !state.collapsed
      };

    case 'EXPORT_JSON':
      const {
        force
      } = action.payload;
      return { ...state,
        exportedJSON: force || !state.exportedJSON ? exportJSON() : state.exportedJSON
      };

    case 'CLEAR_EXPORT_JSON':
      return {
        exportedJSON: null,
        ...state
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const reducedReducers = reduceReducers(createReducer(orm), reducer);
const ormPersistConfig = {
  key: 'MenuBuilderComponent',
  storage,
  blacklist: ['exportedJSON']
};
export default combineReducers({
  MenuBuilderComponent: persistReducer(ormPersistConfig, reducedReducers)
});