export const getState = store => store.RightHeaderContentBuilderComponent;

const getLinksState = store => getState(store) && getState(store).links ? getState(store).links : [];

const getLinkById = (store, id) => getState(store) && getState(store).linksById ? getState(store).linksById[id] : null;

export const getLinks = store => getLinksState(store).map(id => getLinkById(store, id));