export const addLink = ({
  link = '',
  title = '',
  collapsed = false
} = {}) => ({
  type: 'ADD_LINK',
  payload: {
    link,
    title,
    collapsed
  }
});
export const updateLink = link => ({
  type: 'UPDATE_LINK',
  payload: { ...link
  }
});
export const deleteLink = id => ({
  type: 'DELETE_LINK',
  payload: {
    id
  }
});
export const updateState = state => ({
  type: 'UPDATE_STATE',
  payload: { ...state
  }
});
export const exportCode = () => ({
  type: 'EXPORT_CODE',
  payload: {}
});
export const resetState = () => ({
  type: 'RESET_STATE',
  payload: {}
});