import { createSelector } from 'redux-orm';
import orm from './orm';
export const getMenus = createSelector(orm.Menu);
export const getBannerGroups = createSelector(orm.Menu.bannerGroups);
export const getBannerGroupsInRightRegion = createSelector(orm.Menu.bannerGroups, bannerGroups => bannerGroups.filter(bannerGroup => bannerGroup.region === 'right'));
export const getBannerGroupsInBottomRegion = createSelector(orm.Menu.bannerGroups, bannerGroups => bannerGroups.filter(bannerGroup => bannerGroup.region === 'bottom'));
export const getBanners = createSelector(orm.BannerGroup.banners);
export const getCollapsed = state => state.MenuBuilderComponent.collapsed;
export const getExportedJSON = state => state.MenuBuilderComponent.exportedJSON;