export const addItem = ({
  title = 'New Tab',
  content = '',
  collapsed = false
} = {}) => ({
  type: 'ADD_ITEM',
  payload: {
    title,
    content,
    collapsed
  }
});
export const updateItem = banner => ({
  type: 'UPDATE_ITEM',
  payload: { ...banner
  }
});
export const deleteItem = id => ({
  type: 'DELETE_ITEM',
  payload: {
    id
  }
});
export const updateState = state => ({
  type: 'UPDATE_STATE',
  payload: { ...state
  }
});
export const exportCode = () => ({
  type: 'EXPORT_CODE',
  payload: {}
});
export const resetState = () => ({
  type: 'RESET_STATE',
  payload: {}
});