import { combineReducers } from 'redux';
import { persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage'; // defaults to localStorage for web

import initialState from './initialState';
import { htmlEntities } from '../../../utils';
const positionToClassName = {
  after_ratings: 'emthemesModezBannersBlockAfterRating',
  after_addtocart: 'emthemesModezBannersBlockAfterAddToCartButton',
  before_desc: 'emthemesModezBannersBlockBeforeDescription'
};
const positionToGroupName = {
  after_ratings: 'below the product ratings',
  after_addtocart: 'below the Add to Cart button',
  before_desc: 'above the product description'
};

const exportHTML = state => {
  const items = state.items.map(id => state.itemsById[id]);
  return Object.keys(positionToClassName).map(position => {
    const filteredItems = items.filter(item => item.position === position);

    if (filteredItems.length > 0) {
      return [`<!-- Banner displays ${positionToGroupName[position]} -->`, `<div class="emthemesModez-section emthemesModez-section--banners-one">`, `  <div class="emthemesModez-section-inner">`, ...filteredItems.map(({
        id,
        link,
        img,
        alt,
        text,
        type
      }) => (type === 'banner' ? [`    <div class="emthemesModez-bannersContainer emthemesModez-bannersContainer--one">`, `      <div class="emthemesModez-banner">`, `        <div class="emthemesModez-banner-container"><a href="${htmlEntities(link)}"><img class="emthemesModez-banner-image" src="${htmlEntities(img)}" alt="${htmlEntities(alt)}" title="${htmlEntities(alt)}" /></a></div>`, `      </div>`, `    </div>`] : [`    ${text}`]).join('\n')), `  </div>`, `</div>`].join('\n');
    }

    return '';
  }).join('\n\n');
};

const reducer = (state = {}, action) => {
  let {
    id,
    ...payload
  } = action.payload || {};

  switch (action.type) {
    case 'ADD_ITEM':
      id = state.itemNextId;
      return { ...state,
        items: [...state.items, id],
        itemsById: { ...state.itemsById,
          [id]: {
            id,
            ...payload
          }
        },
        itemNextId: id + 1
      };

    case 'UPDATE_ITEM':
      return { ...state,
        itemsById: { ...state.itemsById,
          [id]: { ...state.itemsById[id],
            ...payload
          }
        }
      };

    case 'DELETE_ITEM':
      const newItems = state.items.filter(_id => _id !== id);
      return { ...state,
        items: newItems,
        itemsById: newItems.reduce((newItemsById, id) => ({ ...newItemsById,
          [id]: state.itemsById[id]
        }), {}),
        itemNextId: Math.max(...newItems) + 1
      };

    case 'UPDATE_STATE':
      return { ...state,
        ...action.payload
      };

    case 'TOGGLE_COLLAPSE_GROUP':
      return { ...state,
        collapsedGroups: state.collapsedGroups.indexOf(action.payload.group) !== -1 ? state.collapsedGroups.filter(group => group !== action.payload.group) : [...state.collapsedGroups, action.payload.group]
      };

    case 'EXPORT_CODE':
      return { ...state,
        exportedHTML: exportHTML(state)
      };

    case 'RESET_STATE':
      return initialState();

    default:
      return state;
  }
};

const persistConfig = {
  key: 'ProductBannerBuilderComponent',
  storage
};
export default combineReducers({
  ProductBannerBuilderComponent: persistReducer(persistConfig, reducer)
});